mapper.update:
UPDATE account_verification_tbl
SET fail_count = fail_count + 1
WHERE verification_id = #{verificationId}
AND user_id = #{userId}
AND fail_count < 5

UPDATE account_verification_tbl
SET locked_until = DATE_ADD(NOW(), INTERVAL 5 MINUTE)
WHERE verification_id = #{verificationId}
AND user_id = #{userId}

UPDATE account_verification_tbl
SET verified_yn = 'Y'
WHERE verification_id = #{verificationId}
AND user_id = #{userId}
AND verified_yn = 'N'

mapper.delete:
